import {projectModelPoint} from './model-studio.js?v=motion-v71';
import {cablePoint} from './living-cables.js?v=motion-v71';
const clamp=x=>Math.max(0,Math.min(1,x)),ease=x=>{x=clamp(x);return x*x*(3-2*x)};
export function paintTownFocus(c,time,f={}){if(!f.refineEnabled||f.refineMapFocus===false||time<7.1||time>10.7)return;const q=ease((time-7.1)/1.2),alpha=q*(1-ease((time-10)/.7));c.save();c.globalAlpha=alpha;c.strokeStyle='#edfaff';c.lineWidth=1.6;c.setLineDash([7,6]);c.lineDashOffset=-time*13;c.beginPath();c.ellipse(480,280,105,62,-.16,-Math.PI/2,-Math.PI/2+Math.PI*2*q);c.stroke();c.setLineDash([]);c.beginPath();c.moveTo(480,271);c.lineTo(480,289);c.moveTo(471,280);c.lineTo(489,280);c.stroke();const text=f.refineMapLabel||'HERZOGENAURACH';c.font='800 29px Arial';c.textAlign='center';const width=c.measureText(text).width+38;c.fillStyle='#111d2dd9';c.fillRect(480-width/2,369,width,48);c.fillStyle='#f0f5ff';c.fillText(text,480,403);c.restore();}
export function paintRefinementFinish(c,time,f={}){if(!f.refineEnabled)return;c.save();const strength=f.refineVignette??.08;if(strength>0){const g=c.createRadialGradient(480,260,220,480,260,610);g.addColorStop(0,'#00000000');g.addColorStop(1,`rgba(0,0,0,${Math.min(.3,strength)})`);c.fillStyle=g;c.fillRect(0,0,960,540);}c.restore();}
export function paintRefinementRubble(c,camera,time,f={}){const alpha=f.refineEnabled?(f.refineRubbleDepth??.45):0;if(alpha<=0)return;c.save();c.globalAlpha=Math.min(1,alpha);for(let i=0;i<30;i++){const hash=n=>{const v=Math.sin(n*78.34+19.1)*9717;return v-Math.floor(v)},x=(hash(i+3)-.5)*13,z=-2+hash(i+17)*9,size=.06+hash(i+41)*.18,height=size*.6,pts=[[x-size,0,z],[x,0,z+size],[x+size,0,z],[x+size*.3,height,z-size*.35],[x-size*.7,height*.6,z-size*.4]].map(p=>projectModelPoint(p,camera));if(pts.some(p=>p[2]<.3)||pts.every(p=>p[0]<0)||pts.every(p=>p[0]>960))continue;c.beginPath();pts.forEach((p,j)=>j?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.closePath();c.fillStyle=i%3?'#4c4d47':'#737369';c.fill();c.beginPath();c.moveTo(...pts[0].slice(0,2));c.lineTo(...pts[2].slice(0,2));c.lineTo(...pts[3].slice(0,2));c.closePath();c.fillStyle='#272a27';c.fill();}c.restore();}
export function paintCableEmphasis(c,camera,time,progress,f={}){const strength=f.refineEnabled?(f.refineCableStrength??.85):0;if(!strength||progress<=0)return;c.save();c.globalCompositeOperation='screen';c.globalAlpha=Math.min(.85,progress*strength);c.lineCap='round';for(let strand=0;strand<3;strand++){const points=Array.from({length:49},(_,i)=>projectModelPoint(cablePoint(i/48,strand,time,f),camera));for(const[width,color,opacity]of [[6,'#c4b953',.08],[1.5,'#f4e984',.8]]){c.strokeStyle=color;c.lineWidth=width;c.globalAlpha=progress*strength*opacity;c.beginPath();let pen=false;for(const p of points){if(p[2]<.1){pen=false;continue}if(pen)c.lineTo(p[0],p[1]);else{c.moveTo(p[0],p[1]);pen=true}}c.stroke();}}c.restore();}
// Soft alpha falloff at the eye edges; no hard rectangular crop or opaque colored aperture.
const eyes=new Map();
export function paintSoftEyeFire(c,time,p,size,paint,f={}){const scale=2,w=Math.ceil(size*4*scale),h=Math.ceil(size*2*scale),key=w+'x'+h;let cv=eyes.get(key);if(!cv){cv=Object.assign(document.createElement('canvas'),{width:w,height:h});if(eyes.size>6)eyes.delete(eyes.keys().next().value);eyes.set(key,cv);}const b=cv.getContext('2d');b.setTransform(scale,0,0,scale,0,0);b.globalAlpha=1;b.globalCompositeOperation='source-over';b.clearRect(0,0,w/scale,h/scale);b.save();b.translate(size*2,size);paint(b,[-size,-size*.45,size*2,size*.8]);b.restore();b.globalCompositeOperation='destination-in';b.save();b.translate(size*2,size);b.scale(1,.24);const g=b.createRadialGradient(0,0,size*.12,0,0,size*.83);g.addColorStop(0,'#ffffffff');g.addColorStop(.62,'#ffffffcc');g.addColorStop(1,'#ffffff00');b.fillStyle=g;b.fillRect(-size*2,-size*5,size*4,size*10);b.restore();b.globalCompositeOperation='source-over';c.save();c.translate(...p);c.drawImage(cv,-size*2,-size,size*4,size*2);c.restore();}
